using System;using System.IO;using UnityEditor;using UnityEngine;
public static class GenerateCyberUi {
 public static string Main(){const string root="Assets/Resources/OlcaUI";Directory.CreateDirectory(root);foreach(string name in new[]{"window","description","button-normal","button-selected","button-pressed","button-disabled"}){int n=256;var tex=new Texture2D(n,n,TextureFormat.RGBA32,false);var pixels=new Color[n*n];bool selected=name.EndsWith("selected"),disabled=name.EndsWith("disabled"),dark=name=="description";for(int y=0;y<n;y++)for(int x=0;x<n;x++){int d=Math.Min(Math.Min(x,n-1-x),Math.Min(y,n-1-y));int bevel=Math.Min(Math.Min(x+y,x+n-1-y),Math.Min(n-1-x+y,2*(n-1)-x-y));if(d<3||bevel<20){pixels[y*n+x]=Color.clear;continue;}float t=(float)y/(n-1);Color c=dark?Color.Lerp(new Color(.025f,.10f,.15f,.83f),new Color(.07f,.20f,.27f,.78f),t):Color.Lerp(new Color(.55f,.76f,.83f,.90f),new Color(.79f,.93f,.96f,.80f),t);if(selected)c=Color.Lerp(new Color(.21f,.56f,.65f,.96f),new Color(.60f,.88f,.91f,.94f),t);if(name.EndsWith("pressed"))c=new Color(.28f,.61f,.69f,.96f);if(disabled)c=new Color(.45f,.56f,.60f,.55f);if(d<=5||bevel<=24)c=disabled?new Color(.42f,.57f,.62f,.65f):new Color(.10f,.55f,.70f,.96f);if(d==8||bevel==29)c=new Color(.65f,.94f,1f,disabled ? .30f : .80f);if(d==12)c=new Color(.12f,.39f,.51f,.42f);if((x>=16&&x<39&&y>=n-22&&y<n-18)||(y>=16&&y<38&&x>=n-22&&x<n-18))c=new Color(.17f,.72f,.85f,disabled ? .25f : .85f);if(selected&&x>=18&&x<22&&y>40&&y<n-40)c=new Color(.98f,.86f,.42f,.95f);pixels[y*n+x]=c;}tex.SetPixels(pixels);tex.Apply();string path=root+"/"+name+".png";File.WriteAllBytes(path,tex.EncodeToPNG());UnityEngine.Object.DestroyImmediate(tex);AssetDatabase.ImportAsset(path,ImportAssetOptions.ForceSynchronousImport);var importer=(TextureImporter)AssetImporter.GetAtPath(path);importer.textureType=TextureImporterType.Sprite;importer.spriteImportMode=SpriteImportMode.Single;var settings=new TextureImporterSettings();importer.ReadTextureSettings(settings);settings.spriteMeshType=SpriteMeshType.FullRect;importer.SetTextureSettings(settings);importer.spriteBorder=new Vector4(32,32,32,32);importer.alphaIsTransparency=true;importer.mipmapEnabled=false;importer.textureCompression=TextureImporterCompression.Uncompressed;importer.filterMode=FilterMode.Bilinear;importer.SaveAndReimport();}AssetDatabase.Refresh();return "6 original procedural RGBA sprites, 32px 9-slice borders, no background edits";}
}
